use serde_json::{json,Value};
use ss_core::{java_runtime::Rc,cn::wps::moss::{app::{KmoBookApi::KmoBookApi,xf::{KmoXF::KmoXF,KmoXFManager::KmoXFManager},KmoLocale::KmoLocale,condfmt::KmoCondFmtEval::KmoCondFmtEval},util::KmoRect::KmoRect}};
fn xf(x:&KmoXF)->Value{let f=x.getFont();json!({"fontIndex":x.getFontIndex(),"alignment":x.getAlignment(),"verticalAlignment":x.getVerticalAlignment(),"wrapText":x.getWrapText(),"rotation":x.getRotation(),"indent":x.getIndent(),"shrinkToFit":x.getShrinkToFit(),"locked":x.isLocked(),"hidden":x.isHidden(),"formatIndex":x.getFormatIndex(),"numFormat":x.getNumFormat(),"fillForeground":x.getFillForeground(),"fillBackground":x.getFillBackground(),"fillPattern":x.getAdtlFillPattern(),"borderLeft":x.getBorderLeft(),"borderRight":x.getBorderRight(),"borderTop":x.getBorderTop(),"borderBottom":x.getBorderBottom(),"leftColor":x.getLeftBorderPaletteIdx(),"rightColor":x.getRightBorderPaletteIdx(),"topColor":x.getTopBorderPaletteIdx(),"bottomColor":x.getBottomBorderPaletteIdx(),"fontName":f.as_ref().map(|f|f.getFontName()),"fontHeight":f.as_ref().map(|f|f.getFontHeight()),"boldWeight":f.as_ref().map(|f|f.getBoldWeight()),"italic":f.as_ref().map(|f|f.isItalic()),"fontColor":f.as_ref().map(|f|f.getColorPaletteIndex()),"underline":f.as_ref().map(|f|f.getUnderline()),"strike":f.as_ref().map(|f|f.isStrikeout()),"superSub":f.as_ref().map(|f|f.getSuperSubScript())})}
fn table_styles(book:&ss_core::cn::wps::moss::app::KmoBook::KmoBook)->Value{let Some(t)=book.getXFManager().borrow().getKmoTableStyles()else{return Value::Null;};let styles=t.getTableStyles().map(|v|v.borrow().iter().map(|s|{let elements=s.getTableStyleElements().map(|v|v.borrow().iter().map(|e|{let df=e.getDataFormatting();json!({"type":e.getType().map(|v|format!("{v:?}")),"size":e.getSize(),"dxfId":e.getDxfId(),"fontRaw":df.getFontFormatting().map(|f|f.getRawRecord().borrow().to_vec()),"pattern":df.getPatternFormatting().map(|p|{let p=p.borrow();vec![p.getFillPattern(),p.getFillForegroundColor(),p.getFillBackgroundColor()]}),"border":df.getBorderFormatting().map(|b|{let b=b.borrow();vec![b.getBorderLeft()as i32,b.getBorderRight()as i32,b.getBorderTop()as i32,b.getBorderBottom()as i32,b.getLeftBorderColor(),b.getRightBorderColor(),b.getTopBorderColor(),b.getBottomBorderColor()]}),"numFormat":df.getNumberFormatFormatting().and_then(|n|n.fmtCode())})}).collect::<Vec<_>>()).unwrap_or_default();json!({"name":s.getName(),"pivot":s.isPivot(),"table":s.isTable(),"elements":elements})}).collect::<Vec<_>>()).unwrap_or_default();json!({"defaultTableStyle":t.getDefaultTableStyle(),"defaultPivotStyle":t.getDefaultPivotStyle(),"styles":styles})}
fn main(){KmoLocale::setLocale("zh_CN".into());kfc::cn::wps::kfc::numfmt::i18n::KmoLang::KmoLang::setLocale("zh_CN".into());KmoXFManager::loadBuiltinFormats();let path=std::env::args().nth(1).unwrap();let api=KmoBookApi::KmoBookApi();let book=api.book();book.setAutoCalcOn(false);assert_eq!(api.open(&path,None,true),1);let manager=book.getXFManager().borrow();let xfs=(0..manager.getNumExFormats()).map(|i|manager.getXF(i).map_or(Value::Null,|x|xf(&x))).collect::<Vec<_>>();let count=manager.getNumExFormats();drop(manager);let palette=book.getPalette();let mut sheets=vec![];
for i in 0..book.sheetCount(){let sheet=book.sheetAt(i);let evaluator=Rc::new(KmoCondFmtEval::new());if let Some(t)=evaluator.requestEval(sheet.clone(),Rc::new(vec![KmoRect::KmoRect__bounds(0,0,39,23)])){t.join().unwrap();}let sheet=sheet.borrow();let fmt=sheet.getCFormatter();let mut rules=fmt.getAllCfRule();rules.sort_by_key(|r|r.getRule().getPriority());let rules=rules.iter().map(|c|{let r=c.getRule();let typ=format!("{:?}",r.ruleType().unwrap());let class=match typ.as_str(){"colorScale"=>"KmoColorScale","dataBar"=>"KmoDataBar","iconSet"=>"KmoIconSet","expression"=>"KmoRuleFormula","top10"=>"KmoRuleTop","aboveAverage"=>"KmoRuleAverage","uniqueValues"|"duplicateValues"=>"KmoRuleUnique","timePeriod"=>"KmoRuleTimePeriod","containsText"|"notContainsText"|"beginsWith"|"endsWith"=>"KmoRuleSpecialText","containsBlanks"|"notContainsBlanks"|"containsErrors"|"notContainsErrors"=>"KmoRuleContainSpecial",_=>"KmoRuleCellIs"};json!({"type":typ,"class":class,"priority":r.getPriority(),"stopIfTrue":r.isStopIfTrue(),"dxfId":r.getDxfId(),"extended":c.isExt(),"group":c.getFormatterGroupIndex(),"ranges":c.ranges().unwrap().iter().map(|r|[r.tl.row,r.tl.col,r.br.row,r.br.col]).collect::<Vec<_>>()})}).collect::<Vec<_>>();let mut cells=vec![];for row in 0..40{for col in 0..24{if sheet.getCellData(row,col).isNull(){continue;}let bar=fmt.getDataBar(row,col).map(|b|json!({"priority":b.getPriority(),"color":b.getColor(),"length":b.getLength(),"dir":b.getDir(),"showValue":b.isShowValue()}));let scale=fmt.getColorScale(row,col).map(|s|json!({"priority":s.getPriority(),"color":s.getColor()}));let icon=fmt.getIconSet(row,col).map(|s|json!({"priority":s.getPriority(),"type":s.getType().map(|t|format!("${}",&format!("{t:?}")[1..])),"index":s.getIndex(),"showValue":s.isShowValue()}));let base=sheet.getCellXF__2(row,col).unwrap();cells.push(json!({"row":row,"col":col,"displayText":sheet.getFormattedCellValue(row,col),"generals":fmt.getGenerals(row,col).unwrap_or_default().iter().map(|r|r.getRule().getPriority()).collect::<Vec<_>>(),"showValue":fmt.isShowValue(row,col),"dataBar":bar,"colorScale":scale,"iconSet":icon,"patternXF":xf(&fmt.getMergeXF(row,col,base.clone(),0)),"borderXF":xf(&fmt.getMergeXF(row,col,base.clone(),1)),"fontXF":xf(&fmt.getMergeXF(row,col,base,2))}));}}sheets.push(json!({"index":i,"rules":rules,"cells":cells}));}
let mut root=json!({"tableStyles":table_styles(book.as_ref()),"xfCount":count,"xfs":xfs,"palette":(0..68).map(|i|palette.getRGBColor(i)).collect::<Vec<_>>(),"paletteModified":palette.isPaletteMod(),"basicColors":palette.getBasicColors().borrow().to_vec(),"sheets":sheets});let session=ss_core::api::SpreadsheetSession::SpreadsheetSession::open_path(&path,Default::default());root["inputSha256"]=json!(session.input_sha256());println!("{}",serde_json::to_string_pretty(&root).unwrap());}
